mapper.select:
SELECT id, scan_batch_id AS scanBatchId, shelve_id AS shelveId, campus_name AS campusName, room_id AS roomId, room_name AS roomName, position_x AS positionX, position_y AS positionY, position_label AS positionLabel, status_code AS statusCode, status_label AS statusLabel, pi_name AS piName, department_name AS departmentName, project_pi_name AS projectPiName, detail_name AS detailName, detail_description AS detailDescription, cage_box_qr_code AS cageBoxQrCode, cage_box_json AS cageBoxJson, animal_cage_type AS animalCageType, scanned_at AS scannedAt FROM cage_special_status_snapshot WHERE scan_batch_id = #{scanBatchId}
AND status_code = #{statusCode}
ORDER BY room_name, shelve_id, position_y, position_x
LIMIT #{limit} OFFSET #{offset}

SELECT shelve_id AS shelveId, animal_cage_type AS animalCageType, COUNT(*) AS cnt FROM cage_special_status_snapshot WHERE scan_batch_id = #{scanBatchId} AND status_code = 'NORMAL' AND shelve_id IN
#{id}
GROUP BY shelve_id, animal_cage_type

SELECT DISTINCT shelve_id AS shelveId, shelve_id AS shelveName, campus_name AS campusName, room_name AS roomName, CAST(room_id AS CHAR) AS roomId FROM cage_special_status_snapshot WHERE scan_batch_id = #{scanBatchId} AND (
department_name = #{g} OR project_pi_name = #{g} OR (project_pi_name != '' AND #{g} LIKE CONCAT('%', project_pi_name, '%')) OR (department_name != '' AND #{g} LIKE CONCAT('%', department_name, '%')) OR (project_pi_name != '' AND project_pi_name = SUBSTRING_INDEX(#{g}, '的', 1)) OR (project_pi_name != '' AND project_pi_name LIKE CONCAT(SUBSTRING_INDEX(#{g}, '的', 1), '%'))
) ORDER BY campus_name, room_name, shelve_id
